import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String s = next(), t = next();
        // direction: sign of the first differing position; later positions should oppose it
        int direction = 0;
        long same = 0, opposite = 0;
        for (int i = 0; i < s.length(); i++) {
            char a = s.charAt(i), b = t.charAt(i);
            if (a == b) continue;
            int sign = a > b ? 1 : -1;
            if (direction == 0) direction = sign;
            else if (sign == direction) same++;
            else opposite++;
        }
        System.out.println(direction != 0 ? Math.min(same, opposite + 1) : 0);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s, t := next(), next()
	// direction: sign of the first differing position; later positions should oppose it
	direction, same, opposite := 0, 0, 0
	for i := range s {
		if s[i] == t[i] {
			continue
		}
		sign := -1
		if s[i] > t[i] {
			sign = 1
		}
		if direction == 0 {
			direction = sign
		} else if sign == direction {
			same++
		} else {
			opposite++
		}
	}
	if direction == 0 {
		fmt.Println(0)
	} else {
		fmt.Println(min(same, opposite+1))
	}
}
